{
  "sop_id": "SOP-014",
  "title": "Purchase Request Processing",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to self",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Validate item descriptions, quantities, specifications and required-by date",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Check budget head and cost centre against latest budget report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Choose sourcing route and estimate value",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Prepare PR note and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "above HOD limit"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Finance",
      "item": "Budget confirmation",
      "parallel_group": "true"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
